<?php require __DIR__.'/inc/header.php';$title='Inventory';$rows=db()->query('SELECT v.*,p.name product_name,p.sku product_sku,c.type FROM variants v JOIN products p ON p.id=v.product_id JOIN categories c ON c.id=p.category_id ORDER BY v.stock ASC')->fetchAll();?><div class="flex justify-between mb-6"><div><div class="text-xs tracking-[.2em] text-slate-400 font-black">INVENTORY</div><h1 class="text-3xl font-black">Stock Management</h1></div></div><div class="bg-white border rounded-2xl overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Product</th><th class="p-3 text-left">Variant</th><th class="p-3 text-left">SKU</th><th class="p-3 text-left">Stock</th><th class="p-3 text-left">Threshold</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t"><td class="p-3 font-bold"><?=e($r['product_name'])?></td><td class="p-3"><?=e(trim(($r['size']??'').' '.($r['color']??'')))?></td><td class="p-3 text-xs text-slate-400"><?=e($r['sku'])?></td><td class="p-3 <?=($r['stock']<=$r['low_stock_threshold']?'text-rose-600 font-black':'font-bold')?>"><?=$r['stock']?> <?=($r['stock']<=$r['low_stock_threshold']?'· LOW':'')?></td><td class="p-3"><?=$r['low_stock_threshold']?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/inc/footer.php';?>
